using System.Text;
using System.Text.Json;
internal static class LibraryStockRowTests {
 internal static async Task Run(){
  var root=Path.Combine(Path.GetTempPath(),"LibraryStockRow-"+Guid.NewGuid().ToString("N"));var h=new SimAssemblyHeader("01PART                ","fixture","V1.2","PART                ","PART","A","202020","A",false);var key=h.SourceKeyRaw;var store=new SimLibraryBomStore(root,()=>[h]);var actor=new SimPersona("fixture","fixture","Fixture","ACTIVE",[],[],true,"fixture");
  void Check(bool b,string message){if(!b)throw new Exception(message);}async Task Reject(Func<Task> f){try{await f();}catch(SimRfqIntakeProblem){return;}throw new Exception("Expected stock validation rejection");}
  string Line(params string[] cells)=>string.Join('\t',cells)+"\n";
  var txt=string.Join('\t',SimVproParser.Headers)+"\tDRAW#=PART REV A\n"+Line("088","F2-342","36 POSITION STOCK","","1","1","EA","1","0","0","0","P","")+Line("089","929647-04-36-1","36 POSITION STOCK","","10",".0001","EA","1","0","0","0","P","")+Line("090","","(18) J2,3,4,5,6 - CUT TO SIZE","","0","0","","0","0","0","0","","")+Line("093","PRECUT","OPTIONAL PRE-CUT","","10",".0001","","1","0","0","0","P","")+Line("094","","(NOB) J2","","0","0","","0","0","0","0","","");
  var v=await store.Get(key,actor);v=await store.Change(new(key,v.Token,"START"),actor);v=await store.Change(new(key,v.Token,"IMPORT",FileName:"stock.txt",TextBase64:Convert.ToBase64String(Encoding.ASCII.GetBytes(txt))),actor);
  Check(v.PreparationRowIds!.Length==0&&v.SourceInstructionRowIds!.SequenceEqual(new[]{"vpro-088"}),"source cut note advisory");var r=v.Record.Draft!.Rows[0];Check(r.Quantity=="1"&&r.Unit=="EA"&&!r.PreparationRequired&&!v.Record.Draft.PreparationAssessed,"source stock quantity preserved, no fabricated preparation completion");
  v=await store.Change(new(key,v.Token,"ALTERNATE",RowId:r.Id,AlternateId:r.Alternates[0].Id,AlternateDecision:"APPROVE_SOURCE"),actor);Check(v.Record.Draft!.Rows[0].SelectedAlternateId is null,"approval does not invent primary identity");
  LibraryRowEdit Edit(LibraryBomRow row)=>new(row.Id,row.Find,row.SourcePartNumber,row.Description,row.Quantity,row.Unit,row.ReferenceDesignators,row.IdentityBasis,row.ManufacturerPartNumber,row.ManufacturerName,row.IdentityConfirmed,false,row.Notes,row.PreparationRequired,row.SelectedAlternateId);
  var rows=v.Record.Draft.Rows.Select(Edit).ToArray();rows[0]=rows[0] with{SelectedAlternateId=r.Alternates[0].Id};
  v=await store.Change(new(key,v.Token,"ACCEPT_ROW",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",Rows:rows,RowId:r.Id),actor);Check(v.Record.Draft!.Rows[0].Acceptance is not null&&v.Record.Draft.Rows[1].Quantity=="0","stock accepts normally, optional demand unchanged");
  var hash=v.Record.Draft.EvidenceHash;rows[0]=rows[0] with{Quantity="2"};v=await store.Change(new(key,v.Token,"SAVE",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",Rows:rows),actor);Check(v.Record.Draft!.Rows[0].Acceptance is null,"quantity edit invalidates acceptance");
  v=await store.Change(new(key,v.Token,"ACCEPT_ROW",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",Rows:rows,RowId:r.Id),actor);var reopened=await new SimLibraryBomStore(root,()=>[h]).Get(key,actor);Check(reopened.Record.Draft!.Rows[0].Quantity=="2"&&reopened.Record.Draft.Rows[0].Acceptance is not null,"explicit stock quantity and acceptance reopen");Check(reopened.Record.Draft.EvidenceHash==hash&&reopened.Record.Draft.Import!.VproImport.SourceNotes!.Any(n=>n.Text.Contains("CUT TO SIZE")),"raw note/hash remains");
  var blocked=rows.ToArray();blocked[0]=blocked[0] with{PreparationRequired=true};await Reject(async()=>await store.Change(new(key,v.Token,"ACCEPT_ROW",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",Rows:blocked,RowId:r.Id),actor));Check((await store.Get(key,actor)).Token==v.Token,"explicit preparation failure atomic");
  rows[1]=rows[1] with{IdentityBasis="MFG",ManufacturerPartNumber="PRECUT",IdentityConfirmed=true};v=await store.Change(new(key,v.Token,"ACCEPT_ROW",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",Rows:rows,RowId:rows[1].Id),actor);Check(v.Blockers.Length==0,"source note does not require preparation ritual for BOM review");v=await store.Change(new(key,v.Token,"SUBMIT"),actor);Check(v.Record.Reviews.Single().Status=="SUBMITTED"&&v.Record.Reviews.Single().ReviewedBy is null,"final Technical Review approval still separate");var snapshot=JsonSerializer.Serialize(v.Record.Reviews.Single().Snapshot,SimLibraryBomStore.Json);await Reject(async()=>await store.Change(new(key,v.Token,"ACCEPT_ROW",Rows:rows,RowId:r.Id),actor));Check(JsonSerializer.Serialize((await store.Get(key,actor)).Record.Reviews.Single().Snapshot,SimLibraryBomStore.Json)==snapshot,"submitted history frozen");
  Console.WriteLine("PASS purchased stock row: source note advisory, explicit alternate/primary/row acceptance, quantity editing/reload, independent zero NOB, preserved raw evidence, explicit preparation guard and frozen final-review boundary.");
 }
}
